// HasIncidentInvestigation applies the HasEdge predicate on the "incident_investigation" edge.
func HasIncidentInvestigation() predicate.IncidentInvestigationUpdateEntry {
	return predicate.IncidentInvestigationUpdateEntry(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, IncidentInvestigationTable, IncidentInvestigationColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasIncidentInvestigationWith applies the HasEdge predicate on the "incident_investigation" edge with a given conditions (other predicates).
func HasIncidentInvestigationWith(preds ...predicate.IncidentInvestigation) predicate.IncidentInvestigationUpdateEntry {
	return predicate.IncidentInvestigationUpdateEntry(func(s *sql.Selector) {
		step := newIncidentInvestigationStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

